      es: ["Es el asentamiento suajili habitado continuamente más antiguo de la costa de África Oriental.", "En 2001, el casco antiguo de Lamu fue declarado Patrimonio de la Humanidad por la UNESCO.", "Son típicas las puertas de madera tallada y la mampostería de piedra de coral.", "Los vehículos motorizados están prohibidos; predominan los burros y el tráfico peatonal.", "El fuerte de Lamu fue construido entre 1813 y 1821 bajo el dominio omaní.", "La mezquita de Riyadha es un centro importante de erudición islámica desde 1900.", "El Festival Cultural de Lamu celebra veleros, poesía y tradiciones locales."],
      pt: ["É o assentamento suaíli continuamente habitado mais antigo na costa da África Oriental.", "Em 2001, a Cidade Velha de Lamu foi declarada Património Mundial pela UNESCO.", "São típicas as portas de madeira entalhada e a alvenaria de pedra de coral.", "Veículos motorizados são proibidos; burros e tráfego pedonal dominam.", "O Forte de Lamu foi construído entre 1813 e 1821 sob domínio omanense.", "A Mesquita de Riyadha é um centro importante de erudição islâmica desde 1900.", "O Lamu Cultural Festival celebra veleiros, poesia e tradições locais."],
      fr: ["C'est le plus ancien établissement swahili habité de manière continue sur la côte est-africaine.", "En 2001, la vieille ville de Lamu a été classée au patrimoine mondial de l'UNESCO.", "Les portes en bois sculpté et les murs en pierre de corail sont typiques.", "Les véhicules motorisés sont interdits ; les ânes et la circulation piétonne dominent.", "Le fort de Lamu a été construit entre 1813 et 1821 sous domination omanaise.", "La mosquée Riyadha est un centre important d'érudition islamique depuis 1900.", "Le festival culturel de Lamu célèbre les voiliers, la poésie et les traditions locales."],
