      es: ["Era la antigua casa de campo de la autora danesa Karen Blixen.", "Blixen vivió allí desde 1917 hasta 1931.", "La casa se encuentra en el barrio de Nairobi llamado Karen, nombrado en su honor.", "Originalmente era el centro de una plantación de café de 4500 acres.", "Sus experiencias allí fueron plasmadas en 'Memorias de África'.", "El gobierno keniano se hizo cargo de la casa en 1964 y la inauguró como museo en 1986.", "La película de Hollywood 'Memorias de África' se estrenó en 1985."],
