      fr: ["C'était l'ancienne ferme de l'écrivaine danoise Karen Blixen.", "Blixen y a vécu de 1917 à 1931.", "La maison se trouve dans le quartier de Nairobi appelé Karen, nommé d'après elle.", "À l'origine, elle était le centre d'une plantation de café de 4 500 acres.", "Ses expériences là-bas ont été relatées dans « La Ferme africaine ».", "Le gouvernement kényan a repris la maison en 1964 et l'a ouverte comme musée en 1986.", "Le film hollywoodien « Out of Africa » est sorti en 1985."],
