    coords: [39.854, -3.633],
    name: {
      de: "Mnarani Ruinen",
      hu: "Mnarani romjai",
      ro: "Ruinele Mnarani",
      en: "Mnarani Ruins"},
    image: "/poi-images/mnarani-ruins-history-v2.webp",
    descriptionAdvanced: {
      de: "Die Mnarani-Ruinen bestehen aus den architektonischen Überresten von zwei Swahili-Moscheen und mehreren Gräbern, die auf einer Klippe über dem Kilifi Creek an der kenianischen Küste liegen. Die Siedlung Mnarani, die hauptsächlich aus dem 14. und 15. Jahrhundert stammt, war ein wichtiger Küstenaußenposten, der durch Handel und maritime Aktivitäten florierte. Die Große Moschee, die um 1425 erbaut wurde, ist besonders bemerkenswert für ihre komplizierten Korallenschnitzereien und einen gut erhaltenen Mihrab, der das hohe handwerkliche Niveau der damaligen Zeit anzeigt. Die Stätte enthält auch eine kleinere Moschee aus dem 16. Jahrhundert und mehrere Säulengräber, die mit Porzellaneinsätzen verziert sind, was den Reichtum und den sozialen Status der Bewohner widerspiegelt. Mnarani wurde schließlich im frühen 17. Jahrhundert nach Überfällen der Galla und der allgemeinen Instabilität der Küstenregion zerstört und verlassen. Moderne Erhaltungsbemühungen konzentrieren sich darauf, die Korallenstrukturen vor Erosion zu schützen und den historischen Kontext für das komplexe soziale und religiöse Leben der mittelalterlichen Swahili-Gemeinschaften zu vermitteln.",
      hu: "A Mnarani-romok két szuahéli mecset és több sír építészeti maradványaiból állnak, amelyek a kenyai tengerparton, a Kilifi-öbölre néző magaslaton találhatók. A főként a 14. és 15. századból származó Mnarani település fontos tengerparti előőrs volt, amely a kereskedelem és a tengeri tevékenységek révén virágzott. Az 1425 körül épült Nagy Mecset különösen figyelemre méltó bonyolult korallfaragásai és jó állapotban fennmaradt mihrábja miatt, amely a korszak magas szintű kézművességét jelzi. A helyszínen található egy kisebb, 16. századi mecset is, valamint több, porcelánbetétekkel díszített oszlopsír, amelyek a lakók gazdagságát és társadalmi státuszát tükrözik. Mnarani végül a 17. század elején pusztult el és néptelenedett el a galla nép támadásai és a tengerparti régió általános instabilitása következtében. A modern megőrzési erőfeszítések a korallstruktúrák erózió elleni védelmére és a középkori szuahéli közösségek összetett társadalmi és vallási életének bemutatására összpontosítanak.",
      ro: "Ruinele Mnarani constau în rămășițele arhitecturale a două moschei Swahili și a mai multor morminte situate pe o faleză care domină brațul Kilifi Creek de pe coasta kenyană. Datând în principal din secolele al XIV-lea și al XV-lea, așezarea Mnarani a fost un avanpost de coastă important care a prosperat prin comerț și activități maritime. Marea Moschee, construită în jurul anului 1425, este deosebit de notabilă pentru sculpturile sale complicate în corali și un mihrab bine conservat care indică nivelul ridicat de măiestrie al epocii. Situl conține, de asemenea, o moschee mai mică din secolul al XVI-lea și câteva morminte cu stâlpi decorate cu inserții de porțelan, reflectând bogăția și statutul social al locuitorilor. Mnarani a fost în cele din urmă distrus și abandonat la începutul secolului al XVII-lea, în urma raidurilor populației Galla și a instabilității generale din regiunea de coastă. Eforturile moderne de conservare se concentrează pe protejarea structurilor de corali de eroziune și pe furnizarea contextului istoric pentru viața socială și religioasă complexă a comunităților Swahili medievale.",
      en: "The Mnarani Ruins consist of the architectural remains of two Swahili mosques and several tombs located on a bluff overlooking Kilifi Creek on the Kenyan coast. Dating back primarily to the 14th and 15th centuries, the settlement of Mnarani was an important coastal outpost that prospered through trade and maritime activities. The Great Mosque, built around 1425, is particularly noteworthy for its intricate coral carvings and a well-preserved mihrab that indicates the high level of craftsmanship of the era. The site also contains a smaller mosque from the 16th century and several pillar tombs decorated with porcelain inserts, reflecting the wealth and social status of the inhabitants. Mnarani was eventually destroyed and abandoned in the early 17th century following raids by the Galla people and the general instability of the coastal region. Modern preservation efforts focus on protecting the coral structures from erosion and providing historical context for the complex social and religious life of medieval Swahili communities.",
      es: "Las ruinas de Mnarani se encuentran en una colina sobre el Kilifi Creek y muestran un asentamiento suajili que unía estrechamente comercio, religión y poder. Fundado a principios del siglo XIV, el lugar se convirtió en un importante centro costero con mezquita, tumbas y casas de piedra de coral. Destaca especialmente el mihrab finamente tallado de la Gran Mezquita, en el que incluso se conservó porcelana Ming. La ubicación en la cresta de la colina era estratégica, pero la ciudad no sobrevivió permanentemente a los ataques y tensiones políticas de la costa. Hoy las ruinas parecen silenciosas, pero son muy claras de interpretar.",
      pt: "As ruínas de Mnarani situam-se numa colina sobre o Kilifi Creek e mostram um assentamento suaíli que unia estreitamente comércio, religião e poder. Fundado no início do século XIV, o local tornou-se um importante centro costeiro com mesquita, túmulos e casas de pedra de coral. Destaca-se particularmente o Mihrab finamente esculpido da Grande Mesquita, no qual até porcelana Ming foi preservada. A localização na crista da colina era estratégica, mas a cidade não sobreviveu permanentemente aos ataques e tensões políticas da costa. Hoje, as ruínas parecem silenciosas, mas são muito claras de ler.",
      fr: "Les ruines de Mnarani sont situées sur une colline surplombant le Kilifi Creek et présentent un établissement swahili qui associait étroitement commerce, religion et pouvoir. Fondé au début du XIVe siècle, le lieu est devenu un centre côtier important avec une mosquée, des tombeaux et des maisons en pierre de corail. Le mihrab finement sculpté de la Grande Mosquée, où de la porcelaine Ming a même été conservée, est particulièrement remarquable. L'emplacement sur la crête était stratégique, mais la ville n'a pas survécu durablement aux attaques et aux tensions politiques de la côte. Aujourd'hui, les ruines sont silencieuses mais très lisibles.",
    },
