      ro: ["Oraș Swahili antic fondat în secolul al XIV-lea.", "Prezintă două moschei și câteva morminte cu piloni decorate.", "Marea Moschee datează din aproximativ anul 1425.", "Domină apele adânci ale brațului Kilifi Creek.", "Distrus de atacatorii Galla la începutul secolului al XVII-lea.", "Conține un puț din secolul al XV-lea încă vizibil astăzi."],
      en: ["Ancient Swahili town founded in the 14th century.", "Features two mosques and several decorated pillar tombs.", "The Great Mosque dates back to approximately 1425.", "Overlooks the deep waters of the Kilifi Creek.", "Destroyed by Galla raiders in the early 17th century.", "Contains a 15th-century well still visible today."],
      es: ["El asentamiento fue fundado a principios del siglo XIV.", "Se encuentra en una colina sobre el Kilifi Creek.", "La Gran Mezquita posee un mihrab finamente tallado con porcelana Ming.", "Hay numerosas tumbas de pilares de piedra de coral bajo baobabs.", "Mnarani prosperó con el comercio hacia Omán y Persia.", "A finales del siglo XVI, el lugar fue abandonado tras las incursiones Galla.", "El estado de Kenia protegió Mnarani como monumento histórico."],
