      fr: ["L'établissement a été fondé au début du XIVe siècle.", "Il est situé sur une colline surplombant le Kilifi Creek.", "La Grande Mosquée possède un mihrab finement sculpté avec de la porcelaine Ming.", "Il y a de nombreuses tombes à piliers en pierre de corail sous des baobabs.", "Mnarani a prospéré grâce au commerce avec l'Oman et la Perse.", "À la fin du XVIe siècle, le site fut abandonné suite à des raids Galla.", "L'État kényan a classé Mnarani comme monument historique protégé."],
