    coords: [36.786, -1.325],
    name: {
      de: "Uhuru Gärten",
      hu: "Uhuru Kertek",
      ro: "Grădinile Uhuru",
      en: "Uhuru Gardens"},
    image: "/poi-images/uhuru-gardens-history-v2.webp",
    descriptionAdvanced: {
      de: "Uhuru Gardens ist ein historischer Gedenkpark an der Lang'ata Road in Nairobi und dient als Ort, an dem Kenia am 12. Dezember 1963 offiziell seine Unabhängigkeit von der britischen Herrschaft erlangte. An diesem Ort wurde der Union Jack eingeholt und zum ersten Mal die kenianische Nationalflagge gehisst, was das Ende der Kolonialzeit markierte. Der Park beherbergt das Unabhängigkeits-Gedenkmonument, eine 24 Meter hohe Säule, die ein Paar Hände trägt, die ein Herz und eine Taube halten, was die Einheit und den Frieden der neuen Nation symbolisiert. Ein weiteres bedeutendes Wahrzeichen innerhalb der Gärten ist das 1973 errichtete Denkmal zur Feier des zehnjährigen Bestehens der Unabhängigkeit, das den Kampf um die Freiheit durch verschiedene Skulpturen darstellt. Die Stätte ist auch deshalb bedeutend, weil sie während des Ausnahmezustands als Lager für Mau-Mau-Häftlinge genutzt wurde, was der Feier der Freiheit eine Ebene tiefer historischer Ernsthaftigkeit verleiht. In den letzten Jahren wurde der Park umfassend renoviert und umfasst nun ein Weltklassemuseum und verbesserte Freizeiteinrichtungen, was seine Rolle als Mittelpunkt für Nationalstolz und historische Reflexion sichert.",
      hu: "Az Uhuru Gardens egy történelmi emlékpark a nairobi Lang'ata úton, azon a helyen, ahol Kenya 1963. december 12-én hivatalosan is elnyerte függetlenségét a brit uralom alól. Ezen a helyszínen vonták le a brit zászlót és vonták fel először a kenyai nemzeti lobogót, kijelölve a gyarmati korszak végét. A parkban található a Függetlenségi Emlékmű, egy 24 méter magas oszlop, amely egy szívet és egy galambot tartó kezet formáz, jelképezve az új nemzet egységét és békéjét. A kertek másik jelentős nevezetessége az 1973-ban, a függetlenség tízéves évfordulójára épült emlékmű, amely különféle szobrokon keresztül ábrázolja a szabadságharcot. A helyszín azért is jelentős, mert a rendkívüli állapot idején Mau Mau foglyok táboraként szolgált, ami mély történelmi réteget ad a szabadság ünneplésének. Az elmúlt években a park kiterjedt felújításon esett át, amelynek keretében világszínvonalú múzeumot és fejlesztett rekreációs létesítményeket alakítottak ki, biztosítva szerepét a nemzeti büszkeség és a történelmi emlékezet központjaként.",
      ro: "Uhuru Gardens este un parc memorial istoric situat pe Lang'ata Road în Nairobi, servind drept locul în care Kenya și-a câștigat oficial independența față de dominația britanică pe 12 decembrie 1963. În acest loc a fost coborât steagul Union Jack și a fost arborat pentru prima dată steagul național al Kenyei, marcând sfârșitul erei coloniale. Parcul include Monumentul Comemorativ al Independenței, o coloană înaltă de 24 de metri care susține o pereche de mâini care țin o inimă și un porumbel, simbolizând unitatea și pacea noii națiuni. Un alt reper semnificativ în cadrul grădinilor este monumentul din 1973 construit pentru a celebra zece ani de independență, care înfățișează lupta pentru libertate prin diverse sculpturi. Situl este, de asemenea, semnificativ deoarece a fost folosit ca lagăr pentru deținuții Mau Mau în timpul perioadei de urgență, adăugând un strat de profunzime istorică sumbră celebrării libertății. În ultimii ani, parcul a trecut prin renovări extinse pentru a include un muzeu de talie mondială și facilități recreative îmbunătățite, asigurându-și rolul de punct focal pentru mândria națională și reflecția istorică.",
      en: "Uhuru Gardens is a historic memorial park located on Lang'ata Road in Nairobi, serving as the site where Kenya officially gained its independence from British rule on December 12, 1963. It was at this location that the Union Jack was lowered and the Kenyan national flag was hoisted for the first time, marking the end of the colonial era. The park features the Independence Commemorative Monument, a 24-meter high column supporting a pair of hands holding a heart and a dove, symbolizing the unity and peace of the new nation. Another significant landmark within the gardens is the 1973 monument built to celebrate ten years of independence, which depicts the struggle for freedom through various sculptures. The site is also significant as it was used as a camp for Mau Mau detainees during the Emergency period, adding a layer of somber historical depth to the celebration of liberty. In recent years, the park has undergone extensive renovations to include a world-class museum and improved recreational facilities, ensuring its role as a focal point for national pride and historical reflection.",
      es: "Uhuru Gardens es el lugar central de memoria de Kenia para el momento de su independencia. Exactamente aquí se izó la bandera keniana el 12 de diciembre de 1963, después de que se bajara la Union Jack británica. El parque es extenso, se encuentra en Lang'ata y combina monumentos, museos y arquitectura conmemorativa. Especialmente visible es el monumento de 24 metros de altura que recuerda la primera década de la independencia. Tras una gran remodelación, el lugar recibió espacios de exposición adicionales y una narrativa museística más sólida. Quien está aquí no solo ve un parque, sino el escenario oficial del joven estado.",
      pt: "Uhuru Gardens é o local central de memória do Quénia para o momento da independência. Foi precisamente aqui que a bandeira queniana foi hasteada em 12 de dezembro de 1963, após o Union Jack britânico ter sido arriado. O parque é extenso, situa-se em Lang'ata e une monumento, museu e arquitetura memorial. Particularmente visível é o monumento de 24 metros de altura que recorda a primeira década de independência. Após uma grande remodelação, o local recebeu áreas de exposição adicionais e uma narrativa museológica mais forte. Quem aqui está não vê apenas um parque, mas sim o palco oficial do jovem estado.",
      fr: "Les jardins Uhuru sont le lieu de mémoire central du Kenya pour le moment de l'indépendance. C'est précisément ici que le drapeau kenyan a été hissé le 12 décembre 1963, après que l'Union Jack britannique a été amené. Le parc est vaste, situé à Lang'ata, et combine monument, musée et architecture commémorative. Le monument de 24 mètres de haut, qui commémore la première décennie de l'indépendance, est particulièrement visible. Après un réaménagement majeur, le site a été doté d'espaces d'exposition supplémentaires et d'une narration muséale renforcée. En se tenant ici, on ne voit pas seulement un parc, mais la scène officielle du jeune État.",
    },
