      en: ["Site of Kenya's independence declaration on December 12, 1963.", "Features a 24-meter tall Independence Commemorative Monument.", "Location where the first Kenyan national flag was hoisted.", "Designated as a national monument in the year 1966.", "Includes a Mugumo tree planted on the spot of independence.", "Houses the newly constructed Mashujaa Museum."],
      es: ["Aquí se declaró oficialmente la independencia de Kenia el 12 de diciembre de 1963.", "El monumento de 24 metros de altura conmemora diez años de independencia.", "Uhuru Gardens se encuentra en el distrito de Lang'ata, en Nairobi.", "El recinto abarca aproximadamente 35 acres.", "Uhuru significa libertad o independencia en suajili.", "En 2021, el lugar fue objeto de una remodelación masiva.", "Hoy alberga un gran museo nacional de historia y patrimonio cultural."],
      pt: ["A independência do Quénia foi oficialmente declarada aqui em 12 de dezembro de 1963.", "O monumento de 24 metros de altura recorda dez anos de independência.", "Uhuru Gardens situa-se no bairro de Lang'ata em Nairobi.", "O complexo abrange aproximadamente 35 acres.", "Uhuru significa liberdade ou independência em suaíli.", "Em 2021, o local foi massivamente remodelado.", "Hoje, alberga um grande museu nacional de história e património cultural."],
      fr: ["L'indépendance du Kenya y a été officiellement proclamée le 12 décembre 1963.", "Le monument de 24 mètres de haut commémore les dix ans d'indépendance.", "Les jardins Uhuru sont situés dans le quartier de Lang'ata à Nairobi.", "Le site s'étend sur environ 35 acres.", "Uhuru signifie liberté ou indépendance en swahili.", "En 2021, le site a fait l'objet d'un réaménagement massif.", "Il abrite aujourd'hui un grand musée national d'histoire et du patrimoine."],
