    image: "/poi-images/hyrax-hill-history-v2.webp",
    descriptionAdvanced: {
      de: "Das prähistorische Gelände von Hyrax Hill liegt in der Nähe von Nakuru im Rift Valley in Kenia und gilt als eine der bedeutendsten archäologischen Ausgrabungsstätten Ostafrikas. Die Stätte wurde 1926 von Margaret Collyer entdeckt und ab 1937 von der berühmten Archäologin Mary Leakey systematisch ausgegraben. Die Funde belegen eine kontinuierliche Besiedlung über einen Zeitraum von mehr als 3.000 Jahren, beginnend in der Jungsteinzeit bis hin zur Eisenzeit. Besonders markant sind die sogenannten Sirikwa-Löcher, vertiefte Viehgehege, die von einer frühen pastoralistischen Gemeinschaft stammen. Neben Werkzeugen aus Obsidian und Keramikfragmenten wurden hier auch Skelettreste gefunden, die Aufschluss über die Bestattungsrituale der frühen Bewohner geben. Seit 1943 steht das Gelände als Nationalmonument unter Schutz und beherbergt heute ein Museum, das die Entwicklung der Region von der Vorgeschichte bis in die koloniale Ära dokumentiert.",
      hu: "A Hyrax Hill őskori lelőhely és múzeum Kenya Nakuru megyéjében található, a Nagy-hasadékvölgy egyik legfontosabb régészeti területe. A helyszínt 1926-ban Margaret Collyer fedezte fel, majd 1937-ben Mary Leakey végzett itt jelentős ásatásokat, feltárva az emberi települések nyomait a neolitikumtól a vaskorig. A domb nevét a sziklás területen egykor nagy számban élő szirti borzokról kapta. A régészeti feltárások során úgynevezett Sirikwa-lyukakat találtak, amelyek süllyesztett állatkarámokként szolgáltak a késő vaskori közösségek számára. A leletek között obszidiánból készült eszközök, kerámiatöredékek és temetkezési helyek találhatók, amelyek betekintést nyújtanak a térség korai pásztorkodó életmódjába. A területet 1943-ban nyilvánították nemzeti emlékművé, és ma is fontos kutatási központként szolgál, bemutatva a kelet-afrikai civilizáció fejlődését.",
      ro: "Situl preistoric Hyrax Hill, situat în apropierea orașului Nakuru din Kenya, reprezintă unul dintre cele mai importante puncte arheologice din Valea Marelui Rift. Descoperit în 1926 de Margaret Collyer, situl a fost excavat ulterior de Mary Leakey în 1937, relevând straturi de locuire umană care se întind din perioada neolitică până în epoca fierului. Numele colinei provine de la numeroșii hiracși care populau cândva aflorimentele stâncoase din zonă. Printre cele mai semnificative descoperiri se numără „găurile Sirikwa”, care erau incinte adâncite pentru animale, utilizate de comunitățile de păstori de acum câteva secole. Artefactele găsite, inclusiv unelte din obsidian și fragmente de ceramică, oferă informații prețioase despre tehnologia și modul de viață al primilor locuitori. Astăzi, Hyrax Hill este monument național și găzduiește un muzeu care prezintă vizitatorilor evoluția istorică a regiunii pe parcursul a trei milenii.",
      en: "The Hyrax Hill Prehistoric Site and Museum is located near Nakuru in the Rift Valley of Kenya and is considered one of the most important archaeological sites in East Africa. Discovered in 1926 by Margaret Collyer, the site was extensively excavated by Mary Leakey starting in 1937, uncovering evidence of human habitation spanning over 3,000 years. The findings reveal a sequence of occupations from the Neolithic period to the late Iron Age. A notable feature of the site are the Sirikwa holes, which were sunken hollows used as livestock enclosures by early pastoralist communities. Excavations also unearthed obsidian tools, pottery shards, and burial mounds that provide critical insights into the social and technological development of the region's ancient inhabitants. Designated as a National Monument in 1943, Hyrax Hill now serves as a research center and a museum that preserves the prehistoric heritage of the Kenyan interior.",
      es: "Hyrax Hill se encuentra directamente a las afueras de Nakuru y es una colina arqueológica donde se han superpuesto varias épocas. Mary Leakey investigó el lugar ya en 1926 y encontró rastros que van desde la caza de la Edad de Piedra hasta la ganadería de la Edad del Hierro. Son especialmente conocidos los llamados agujeros Sirikwa, estructuras para el ganado y otros animales domésticos. A esto se suman túmulos funerarios y restos de asentamientos que se remontan a unos 3000 años. El nombre hace referencia a los damanes de roca que habitan la colina hasta hoy. Hyrax Hill combina así paisaje, fauna e historia de los asentamientos en un espacio reducido.",
      pt: "Hyrax Hill situa-se diretamente na periferia de Nakuru e é uma colina arqueológica onde várias épocas se sobrepuseram. Mary Leakey investigou o local já em 1926 e encontrou vestígios que vão desde a caça da Idade da Pedra até à pecuária da Idade do Ferro. São particularmente conhecidos os chamados buracos Sirikwa, estruturas para o gado e outros animais domésticos. A isto somam-se túmulos e restos de povoamentos que remontam a cerca de 3000 anos. O nome refere-se aos hyraxes das rochas que habitam a colina até hoje. Hyrax Hill combina assim paisagem, vida selvagem e história do povoamento num espaço reduzido.",
      fr: "Hyrax Hill se trouve directement à la lisière de Nakuru et est une colline archéologique où plusieurs époques se sont superposées. Mary Leakey a exploré le site dès 1926 et y a trouvé des traces allant de la chasse à l'âge de pierre à l'élevage à l'âge du fer. Les « fosses Sirikwa », des structures destinées au bétail et à d'autres animaux domestiques, sont particulièrement célèbres. S'y ajoutent des tumulus et des restes d'habitations remontant à environ 3000 ans. Le nom fait référence aux damans des rochers qui habitent encore la colline aujourd'hui. Hyrax Hill combine ainsi paysage, faune et histoire du peuplement sur un espace restreint.",
    },
