      fr: ["La maison se trouve à Maralal, dans le comté de Samburu.", "Jomo Kenyatta y a été détenu de 1959 à août 1961.", "C'était sa dernière station de détention coloniale.", "C'est ici qu'ont eu lieu les dernières négociations avec les autorités britanniques.", "Le bâtiment est un modeste bungalow de trois pièces.", "Le mobilier d'origine et des objets historiques y sont conservés.", "La maison est un symbole du passage à l'indépendance."],
