      en: ["Founded in 1846 by Johann Ludwig Krapf", "Established as the first Christian mission in Kenya", "Site of the first Swahili Bible translation", "Located approximately 25 km northwest of Mombasa", "Features the original church building from 1848", "Officially opened as a museum in 1998"],
