      fr: ["La première station missionnaire chrétienne du Kenya a été fondée à Rabai en 1846.", "Johann Ludwig Krapf était le missionnaire allemand de la CMS à l'origine du projet.", "Rabai est situé à environ 25 kilomètres au nord-ouest de Mombasa.", "Le lieu a également servi de refuge aux esclaves libérés.", "On y trouve le plus ancien bâtiment d'église chrétienne encore en activité au Kenya.", "Le site marque le début de l'éducation occidentale formelle dans le pays.", "Le musée décrit le conflit entre les missionnaires et les Mijikenda."],
