      pt: "Um importante sítio pré-histórico onde foram descobertos fósseis de Kenyapithecus wickeri, um antepassado precoce dos grandes símios.",
      fr: "Un site préhistorique majeur où ont été découverts des fossiles de Kenyapithecus wickeri, un ancêtre précoce des grands singes.",
