      hu: ["Őslénytani lelőhely", "Kenyapithecus", "Felfedezve 1961-ben", "14 millió éves"],
      ro: ["Sit paleontologic", "Kenyapithecus", "Descoperit în 1961", "Vechi de 14 milioane de ani"],
      en: ["Paleontological site", "Kenyapithecus", "Discovered in 1961", "14 million years old"],
      es: ["Sitio paleontológico", "Kenyapithecus", "Descubierto en 1961", "14 millones de años de antigüedad"],
