      ro: "O zonă istorică cunoscută pentru rezistența poporului Nandi împotriva dominației coloniale britanice.",
      en: "A historic area known for the Nandi resistance against British colonial rule under the leadership of Koitalel Arap Samoei.",
      es: "Un área histórica conocida por la resistencia de los Nandi contra el dominio colonial británico bajo el liderazgo de Koitalel Arap Samoei.",
      pt: "Uma área histórica conhecida pela resistência dos Nandi contra o domínio colonial britânico sob a liderança de Koitalel Arap Samoei.",
