    type: "historical",
    parent: "KE-22",
    coords: [36.711, -1.238],
    name: {
      de: "Fort Smith",
      hu: "Fort Smith",
      ro: "Fort Smith",
      en: "Fort Smith"},
    image: "/poi-images/fort-smith-history-v2.webp",
    descriptionAdvanced: {
      en: "Fort Smith is a highly significant, though heavily ruined, colonial military outpost located in the rapidly suburbanizing area of Kabete, just west of Nairobi. Established in 1891 by the Imperial British East Africa Company (IBEAC), it was constructed specifically to militarily secure the crucial caravan route running between Mombasa and Uganda. Surrounded by a massive, deep defensive trench, the fort became a highly intense flashpoint of conflict during the early colonial pacification campaigns against the local Kikuyu population, particularly under the command of the notoriously brutal Captain Francis Hall. Today, the massive trench and scattered earthworks are all that remain, quietly persisting amidst the massive real estate development of modern Kiambu County, serving as a stark reminder of the violent origins of colonial land acquisition.",
      de: "Fort Smith, in der Nähe des heutigen Nairobi gelegen, war ein entscheidender früher kolonialer Außenposten, der von der Imperial British East Africa Company (IBEAC) um 1891 errichtet wurde. Benannt nach Captain Eric Smith, wurde das Fort gebaut, um die Karawanenrouten zu schützen und die Kontrolle über das Kikuyu-Volk auszuüben. Es war ein einfacher, aber effektiver Erdwall mit Gräben und Palisaden. Das Fort wurde zum Schauplatz zahlreicher Konflikte zwischen der IBEAC und den lokalen Kikuyu-Gemeinschaften, die sich der britischen Einmischung widersetzten. Obwohl Fort Smith nach der Verlegung des kolonialen Hauptquartiers nach Nairobi an Bedeutung verlor und heute nur noch wenige Überreste sichtbar sind, markiert es einen entscheidenden Moment in der gewaltsamen Etablierung der britischen Kolonialherrschaft in Kenia.",
      hu: "A Fort Smith, a mai Nairobi közelében, egy kulcsfontosságú korai gyarmati előőrs volt, amelyet a Brit Kelet-afrikai Császári Társaság (IBEAC) épített 1891 körül. Eric Smith kapitányról nevezték el, és az erőd a karavánutak védelmére és a kikuju nép feletti ellenőrzés gyakorlására szolgált. Egyszerű, de hatékony földsánc volt, árkokkal és cölöpfalakkal. Az erőd számos konfliktus helyszíne lett az IBEAC és a brit beavatkozásnak ellenálló helyi kikuju közösségek között. Bár Fort Smith elvesztette jelentőségét, miután a gyarmati központot Nairobiba helyezték át, és ma már csak kevés maradványa látható, döntő pillanatot jelöl a brit gyarmati uralom erőszakos megteremtésében Kenyában.",
      ro: "Fort Smith, situat lângă Nairobiul de astăzi, a fost un avanpost colonial timpuriu crucial, stabilit de Compania Imperială Britanică a Africii de Est (IBEAC) în jurul anului 1891. Numit după căpitanul Eric Smith, fortul a fost construit pentru a proteja rutele caravanelor și pentru a exercita controlul asupra poporului Kikuyu. Era o fortificație simplă, dar eficientă, din pământ, cu șanțuri și palisade. Fortul a devenit scena a numeroase conflicte între IBEAC și comunitățile locale Kikuyu care se opuneau amestecului britanic. Deși Fort Smith și-a pierdut importanța după mutarea sediului colonial la Nairobi și astăzi rămân puține vestigii vizibile, acesta marchează un moment esențial în stabilirea violentă a dominației coloniale britanice în Kenya.",
      es: "Fort Smith, situado cerca de la actual Nairobi, fue un puesto avanzado colonial temprano crucial, establecido por la Imperial British East Africa Company (IBEAC) alrededor de 1891. Nombrado en honor al capitán Eric Smith, el fuerte fue construido para proteger las rutas de las caravanas y ejercer control sobre el pueblo Kikuyu. Era una fortificación de tierra sencilla pero efectiva con fosos y empalizadas. El fuerte se convirtió en el escenario de numerosos conflictos entre la IBEAC y las comunidades locales Kikuyu que se resistían a la interferencia británica. Aunque Fort Smith perdió importancia tras el traslado de la sede colonial a Nairobi y hoy solo quedan pocos restos visibles, marca un momento decisivo en el establecimiento violento del dominio colonial británico en Kenia.",
      pt: "Fort Smith, situado perto da atual Nairobi, foi um posto avançado colonial inicial crucial, estabelecido pela Imperial British East Africa Company (IBEAC) por volta de 1891. Batizado em honra do Capitão Eric Smith, o forte foi construído para proteger as rotas das caravanas e exercer controlo sobre o povo Kikuyu. Era uma fortificação de terra simples mas eficaz, com fossos e paliçadas. O forte tornou-se palco de numerosos conflitos entre a IBEAC e as comunidades locais Kikuyu que resistiam à interferência britânica. Embora o Fort Smith tenha perdido importância após a transferência da sede colonial para Nairobi e hoje restem apenas poucos vestígios visíveis, marca um momento decisivo no estabelecimento violento do domínio colonial britânico no Quénia.",
      fr: "Fort Smith, situé près de l'actuelle Nairobi, était un avant-poste colonial précoce crucial, établi par l'Imperial British East Africa Company (IBEAC) vers 1891. Nommé d'après le capitaine Eric Smith, le fort a été construit pour protéger les routes des caravanes et exercer un contrôle sur le peuple Kikuyu. Il s'agissait d'un rempart de terre simple mais efficace, doté de fossés et de palissades. Le fort devint le théâtre de nombreux conflits entre l'IBEAC et les communautés Kikuyu locales qui résistaient à l'ingérence britannique. Bien que Fort Smith ait perdu de son importance après le transfert du quartier général colonial à Nairobi et qu'il ne reste aujourd'hui que peu de vestiges visibles, il marque un moment décisif dans l'établissement violent de la domination coloniale britannique au Kenya.",
    },
