    name: {
      de: "Ishakani Ruinen",
      hu: "Ishakani romjai",
      ro: "Ruinele Ishakani",
      en: "Ishakani Ruins"},
    image: "/poi-images/ishakani-ruins-history-v2.webp",
    descriptionAdvanced: {
      en: "The Ishakani Ruins represent an incredibly remote, deeply mysterious archaeological site situated on the extreme northern coast of Kenya, literally straddling the Somali border. Dating from the 15th to the 17th centuries, the site is globally renowned for containing the highest concentration of highly elaborate Swahili pillar tombs in East Africa. These massive coral stone structures are uniquely adorned with inset Ming Dynasty porcelain bowls and feature highly complex, deeply carved geometric motifs. Unlike other major Swahili settlements, Ishakani lacks massive palace structures, suggesting it may have served primarily as a highly venerated, deeply sacred burial ground or a specialized outpost for the coastal ivory trade. The extreme geographical isolation of the site has kept it highly preserved, yet deeply under-researched.",
      de: "Die Ishakani-Ruinen, in der Nähe der somalischen Grenze gelegen, sind die Überreste einer alten Swahili-Siedlung, die vor allem für ihre außergewöhnlichen Säulengräber bekannt ist. Diese Gräber, die kunstvoll mit eingelassenen Porzellantellern verziert sind, unterscheiden sich von denen in anderen großen Küstenstädten und deuten auf eine einzigartige lokale Tradition hin. Die Siedlung selbst hatte keine großen Paläste oder Moscheen wie Gedi oder Lamu, was darauf hindeutet, dass sie möglicherweise eine andere Funktion hatte, vielleicht als heilige Begräbnislandschaft für eine Konföderation von Swahili-Clans. Die Archäologie von Ishakani gibt Einblicke in die Vielfalt der Swahili-Kultur und die verschiedenen Arten, wie Gemeinschaften entlang der ostafrikanischen Küste organisiert waren. Die abgelegene Lage hat dazu beigetragen, diese fragilen Strukturen zu erhalten.",
      hu: "Az Ishakani-romok, a szomáliai határ közelében, egy ősi szuahéli település maradványai, amelyek leginkább a kivételes oszlopos sírjaikról ismertek. Ezek a sírok, amelyeket díszesen berakott porcelántányérokkal díszítettek, eltérnek a többi nagy tengerparti városban találhatóktól, és egyedi helyi hagyományra utalnak. Maga a település nem rendelkezett olyan nagy palotákkal vagy mecsetekkel, mint Gedi vagy Lamu, ami arra utal, hogy talán más funkciót töltött be, esetleg egy szuahéli klánszövetség szent temetkezési tájaként. Az ishakani régészet bepillantást enged a szuahéli kultúra sokféleségébe és a kelet-afrikai part menti közösségek szerveződésének különböző módjaiba. A távoli fekvés segített megőrizni ezeket a törékeny építményeket.",
      ro: "Ruinele Ishakani, situate în apropierea graniței cu Somalia, sunt rămășițele unei vechi așezări swahili, renumită în special pentru mormintele sale excepționale cu stâlpi. Aceste morminte, decorate cu farfurii de porțelan încrustate, sunt distincte de cele găsite în alte orașe mari de coastă, sugerând o tradiție locală unică. Așezarea însăși nu avea palate sau moschei mari precum Gedi sau Lamu, ceea ce indică faptul că ar fi putut avea o funcție diferită, poate ca un peisaj funerar sacru pentru o confederație de clanuri swahili. Arheologia de la Ishakani oferă o perspectivă asupra diversității culturii swahili și a diferitelor moduri în care erau organizate comunitățile de-a lungul coastei est-africane. Amplasarea sa izolată a ajutat la conservarea acestor structuri fragile.",
      es: "Las ruinas de Ishakani, situadas cerca de la frontera con Somalia, son los restos de un antiguo asentamiento suajili, conocido principalmente por sus extraordinarias tumbas de pilares. Estas tumbas, decoradas artísticamente con platos de porcelana incrustados, se distinguen de las de otras grandes ciudades costeras y sugieren una tradición local única. El asentamiento en sí no tenía grandes palacios o mezquitas como Gedi o Lamu, lo que indica que pudo tener una función diferente, tal vez como un paisaje funerario sagrado para una confederación de clanes suajili. La arqueología de Ishakani ofrece una visión de la diversidad de la cultura suajili y las diferentes formas en que se organizaban las comunidades a lo largo de la costa de África Oriental. Su ubicación remota ha contribuido a preservar estas estructuras frágiles.",
      pt: "As ruínas de Ishakani, situadas perto da fronteira com a Somália, são os restos de um antigo povoamento Swahili, conhecido principalmente pelos seus extraordinários túmulos de pilares. Estes túmulos, artisticamente decorados com pratos de porcelana incrustados, distinguem-se dos de outras grandes cidades costeiras e sugerem uma tradição local única. O próprio povoamento não tinha grandes palácios ou mesquitas como Gedi ou Lamu, o que indica que poderá ter tido uma função diferente, talvez como uma paisagem funerária sagrada para uma confederação de clãs Swahili. A arqueologia de Ishakani oferece uma visão da diversidade da cultura Swahili e das diferentes formas como as comunidades ao longo da costa da África Oriental se organizavam. A localização remota contribuiu para preservar estas estruturas frágeis.",
      fr: "Les ruines d'Ishakani, situées près de la frontière somalienne, sont les vestiges d'une ancienne colonie swahili, célèbre surtout pour ses tombes à piliers extraordinaires. Ces tombes, artistiquement décorées d'assiettes en porcelaine incrustées, se distinguent de celles des autres grandes villes côtières et suggèrent une tradition locale unique. La colonie elle-même ne possédait pas de grands palais ou de mosquées comme Gedi ou Lamu, ce qui indique qu'elle avait peut-être une fonction différente, peut-être comme paysage funéraire sacré pour une confédération de clans swahilis. L'archéologie d'Ishakani donne un aperçu de la diversité de la culture swahili et des différentes manières dont les communautés étaient organisées le long de la côte est-africaine. Son emplacement reculé a contribué à préserver ces structures fragiles.",
    },
